BS_JS = r'''{const st=document.getElementById('bs'),out=document.getElementById('bsOut');
const play=()=>{const n=1+Math.floor(Math.random()*100);let lo=1,hi=100,tries=0;
 st.innerHTML=`<div style="width:100%"><div class="big" id="bsMsg">1 to 100</div><p class="small" id="bsHint">Guess the number. Binary-search strategy: always guess the middle of what's left.</p><form id="bsF" style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-top:10px"><label for="bsIn" class="small" style="align-self:center">Your guess</label><input id="bsIn" type="number" min="1" max="100" inputmode="numeric" required style="font:16px Nunito;min-height:44px;width:110px;padding:8px 10px;border-radius:12px;border:2px solid var(--line);background:var(--card);color:var(--ink)"><button class="btn solid" type="submit">Guess</button></form></div>`;
 document.getElementById('bsF').addEventListener('submit',e=>{e.preventDefault();const inp=document.getElementById('bsIn');const g=+inp.value;if(!g||g<1||g>100)return;tries++;
  const msg=document.getElementById('bsMsg'),hint=document.getElementById('bsHint');
  if(g===n){const best=tries<=7;st.innerHTML=`<div><div class="big">${n}! In ${tries} ${tries===1?'guess':'guesses'}</div><p>${best?'That is binary-search speed. 7 guesses always suffice for 100 numbers, since 2⁷ = 128.':'Tip: guess the middle each time (50, then 25 or 75…) and you will never need more than 7.'}</p><button class="btn solid" id="bsAgain">Play again</button></div>`;document.getElementById('bsAgain').onclick=play;out.innerHTML='Binary search finds an item in a sorted list of 1,000,000 in about 20 steps. '+(S.games.bs?'':'<b>+20 XP.</b>');S.games.bs=1;save();hud();return}
  if(g<n)lo=Math.max(lo,g+1);else hi=Math.min(hi,g-1);
  msg.textContent=(g<n?'Higher':'Lower')+' than '+g;hint.textContent='The number is between '+lo+' and '+hi+'. The middle would be '+Math.floor((lo+hi)/2)+'. Guesses so far: '+tries;inp.value='';inp.focus()})};
document.getElementById('bsGo').onclick=play;}'''

